-- Phase 46 reuses organizations and establishments as tenant/network/store roots.
alter table public.plans add column if not exists network_governance_enabled boolean not null default true;
alter table public.plans add column if not exists franchise_management_enabled boolean not null default true;
alter table public.plans add column if not exists central_catalog_enabled boolean not null default true;
alter table public.plans add column if not exists network_pricing_enabled boolean not null default true;
alter table public.plans add column if not exists network_benchmarking_enabled boolean not null default true;

create table public.network_brands(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,code text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,code));
create table public.network_regions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,name text not null,manager_user_id uuid references auth.users(id) on delete set null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table public.network_clusters(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,name text not null,code text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,code));
create table public.network_cluster_stores(cluster_id uuid not null references public.network_clusters(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,created_at timestamptz not null default now(),primary key(cluster_id,store_id));
alter table public.establishments add column if not exists network_brand_id uuid references public.network_brands(id) on delete set null;
alter table public.establishments add column if not exists network_region_id uuid references public.network_regions(id) on delete set null;
alter table public.establishments add column if not exists ownership_type text not null default 'company_owned' check(ownership_type in('company_owned','franchise','partner_operated','other'));

create table public.network_role_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,permissions text[] not null default '{}',default_scope text not null check(default_scope in('organization','brand','region','store')),editable boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table public.network_member_scopes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role_template_id uuid references public.network_role_templates(id) on delete set null,scope_type text not null check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid not null,can_view_sensitive_finance boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,user_id,scope_type,scope_id));
create table public.network_governance_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,domain text not null check(domain in('catalog','pricing','suppliers','operations','marketing','workforce','finance','hardware')),config_key text not null,schema_version integer not null default 1,scope_type text not null check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid,value jsonb not null,centrally_managed boolean not null default false,local_override_allowed boolean not null default true,approval_required boolean not null default false,sensitive boolean not null default false,version integer not null default 1,effective_at timestamptz not null default now(),created_by uuid references auth.users(id),created_at timestamptz not null default now(),superseded_at timestamptz,unique(organization_id,domain,config_key,scope_type,scope_id,version));
create table public.network_config_overrides(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,policy_id uuid not null references public.network_governance_policies(id) on delete cascade,value jsonb not null,status text not null default 'active' check(status in('pending','active','rejected','expired','revoked')),reason text,approved_by uuid references auth.users(id),valid_until timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());

create table public.network_rollouts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,type text not null,config_domain text not null,target_scope jsonb not null,status text not null default 'draft' check(status in('draft','scheduled','running','partially_completed','completed','failed','rolled_back')),payload jsonb not null default '{}',impact_preview jsonb not null default '{}',confirmation_token_hash text,idempotency_key text not null,scheduled_at timestamptz,started_at timestamptz,completed_at timestamptz,created_by uuid references auth.users(id),rollback_available boolean not null default false,created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table public.network_rollout_stages(id uuid primary key default gen_random_uuid(),rollout_id uuid not null references public.network_rollouts(id) on delete cascade,stage_order integer not null,stage_type text not null check(stage_type in('pilot','group','network')),status text not null default 'pending' check(status in('pending','running','completed','failed','skipped')),target_count integer not null default 0,processed_count integer not null default 0,created_at timestamptz not null default now(),unique(rollout_id,stage_order));
create table public.network_rollout_targets(id uuid primary key default gen_random_uuid(),rollout_id uuid not null references public.network_rollouts(id) on delete cascade,stage_id uuid references public.network_rollout_stages(id) on delete set null,store_id uuid not null references public.establishments(id) on delete cascade,status text not null default 'pending' check(status in('pending','running','success','failed','skipped','override_conflict','rolled_back')),attempt_count integer not null default 0,last_error text,applied_version integer,idempotency_key text not null,processed_at timestamptz,created_at timestamptz not null default now(),unique(rollout_id,store_id),unique(rollout_id,idempotency_key));

create table public.network_catalog_products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,source_product_id uuid references public.products(id) on delete set null,name text not null,description text,image_url text,category_name text,recipe_snapshot jsonb not null default '{}',modifiers jsonb not null default '[]',sku text,ownership text not null default 'network_managed' check(ownership in('network_managed','locally_managed','hybrid')),allowed_override_fields text[] not null default array['price','availability'],version integer not null default 1,active boolean not null default true,created_at timestamptz not null default now());
create table public.network_catalog_store_state(network_product_id uuid not null references public.network_catalog_products(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,product_id uuid references public.products(id) on delete set null,applied_version integer not null default 0,availability boolean not null default true,local_overrides jsonb not null default '{}',sync_status text not null default 'pending' check(sync_status in('pending','synced','override_conflict','failed')),updated_at timestamptz not null default now(),primary key(network_product_id,store_id));
create table public.network_menu_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete cascade,name text not null,format text not null check(format in('hamburgueria','pizzaria','bar','cafe','restaurante','custom')),definition jsonb not null default '{}',version integer not null default 1,active boolean not null default true,created_at timestamptz not null default now());

create table public.pricing_zones(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,name text not null,code text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,code));
create table public.pricing_zone_stores(zone_id uuid not null references public.pricing_zones(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,primary key(zone_id,store_id));
create table public.network_price_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,network_product_id uuid not null references public.network_catalog_products(id) on delete cascade,pricing_zone_id uuid references public.pricing_zones(id) on delete set null,scope_type text not null check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid,policy_type text not null check(policy_type in('fixed_central','suggested','min_max_range','local_control')),price_cents integer,suggested_price_cents integer,min_price_cents integer,max_price_cents integer,effective_at timestamptz not null default now(),version integer not null default 1,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.network_price_history(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,network_product_id uuid not null references public.network_catalog_products(id) on delete cascade,old_price_cents integer,new_price_cents integer not null,policy_id uuid references public.network_price_policies(id),changed_by uuid references auth.users(id),changed_at timestamptz not null default now());

create table public.network_approved_suppliers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','store')),scope_id uuid,status text not null check(status in('approved','preferred','restricted','blocked')),policy_enforced boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,supplier_id,scope_type,scope_id));
create table public.network_supplier_agreements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,inventory_item_id uuid references public.inventory_items(id) on delete set null,negotiated_price_cents integer,valid_from date not null,valid_to date,applicable_units uuid[] not null default '{}',notes text,created_at timestamptz not null default now());
create table public.supplier_approval_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,supplier_id uuid references public.suppliers(id) on delete set null,reason_type text not null check(reason_type in('price','availability','local_supplier','emergency')),reason text not null,status text not null default 'pending' check(status in('pending','approved','rejected','expired','revoked')),temporary_until timestamptz,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());

create table public.network_operational_standards(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid,name text not null,standard_type text not null check(standard_type in('preparation_time','opening_checklist','closing_checklist','food_safety_internal','customer_service','inventory','cash_control','hardware','cleaning','other')),definition jsonb not null default '{}',version integer not null default 1,optional boolean not null default true,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.network_standard_executions(id uuid primary key default gen_random_uuid(),standard_id uuid not null references public.network_operational_standards(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,status text not null check(status in('compliant','attention','overdue','not_applicable')),components jsonb not null default '[]',score numeric,executed_by uuid references auth.users(id),executed_at timestamptz not null default now(),next_due_at timestamptz);
create table public.network_internal_audits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,standard_id uuid references public.network_operational_standards(id) on delete set null,auditor_user_id uuid references auth.users(id),audit_date date not null,score numeric,score_components jsonb not null default '[]',issues jsonb not null default '[]',follow_up text,created_at timestamptz not null default now());
create table public.network_corrective_actions(id uuid primary key default gen_random_uuid(),audit_id uuid not null references public.network_internal_audits(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,title text not null,owner_user_id uuid references auth.users(id),due_at timestamptz,status text not null default 'open' check(status in('open','in_progress','completed','cancelled')),photo_evidence_path text,created_at timestamptz not null default now());

create table public.network_configuration_drift(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,policy_id uuid references public.network_governance_policies(id) on delete cascade,drift_type text not null check(drift_type in('intentional_override','unauthorized_change','outdated_version','sync_failure')),expected_version integer,actual_version integer,status text not null default 'open' check(status in('open','accepted','remediated','review_requested')),details jsonb not null default '{}',detected_at timestamptz not null default now(),resolved_at timestamptz);
create table public.governance_exception_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,policy_id uuid references public.network_governance_policies(id) on delete set null,policy_type text not null,requested_change jsonb not null,reason text not null,status text not null default 'pending' check(status in('pending','approved','rejected','expired','revoked')),approver_id uuid references auth.users(id),valid_until timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.network_announcements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid,title text not null,body text not null,acknowledgement_required boolean not null default false,published_at timestamptz,expires_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.network_announcement_acknowledgements(announcement_id uuid not null references public.network_announcements(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,acknowledged_at timestamptz not null default now(),primary key(announcement_id,user_id));

create table public.store_opening_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,name text not null,approved_configuration jsonb not null default '{}',version integer not null default 1,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.store_opening_projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,template_id uuid references public.store_opening_templates(id) on delete set null,source_store_id uuid references public.establishments(id) on delete set null,brand_id uuid references public.network_brands(id) on delete set null,region_id uuid references public.network_regions(id) on delete set null,pricing_zone_id uuid references public.pricing_zones(id) on delete set null,status text not null default 'not_started' check(status in('not_started','in_progress','ready_for_test','ready_for_launch','active')),readiness jsonb not null default '{}',test_order_id uuid references public.orders(id) on delete set null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table public.fact_network_rollouts(rollout_id uuid primary key,organization_id uuid not null,rollout_type text not null,status text not null,target_count integer not null,success_count integer not null,failed_count integer not null,started_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_store_compliance(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid not null,standard_type text not null,status text not null,score numeric,measured_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_governance_exceptions(exception_id uuid primary key,organization_id uuid not null,store_id uuid not null,policy_type text not null,status text not null,valid_until timestamptz,created_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_store_benchmarks(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid not null,metric_key text not null,metric_value numeric,network_mean numeric,network_median numeric,top_quartile numeric,percentile numeric,sample_size integer not null,peer_group text,measured_at date not null,loaded_at timestamptz not null default now(),unique(store_id,metric_key,measured_at));
create table public.dim_brand(brand_id uuid primary key,organization_id uuid not null,name text not null,code text not null,active boolean not null,loaded_at timestamptz not null default now());
create table public.dim_region(region_id uuid primary key,organization_id uuid not null,brand_id uuid,name text not null,active boolean not null,loaded_at timestamptz not null default now());
create table public.dim_cluster(cluster_id uuid primary key,organization_id uuid not null,brand_id uuid,name text not null,code text not null,active boolean not null,loaded_at timestamptz not null default now());
create table public.dim_store_ownership_type(ownership_type text primary key,label text not null,description text not null);
insert into public.dim_store_ownership_type values('company_owned','Unidade própria','Classificação operacional.'),('franchise','Franquia','Classificação operacional, sem efeito jurídico automático.'),('partner_operated','Operada por parceiro','Classificação operacional.'),('other','Outro','Classificação operacional.') on conflict do nothing;
create table public.network_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,scope_type text,scope_id uuid,preview jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create index network_brands_org_idx on public.network_brands(organization_id,active);
create index network_regions_org_idx on public.network_regions(organization_id,brand_id,active);
create index network_regions_manager_idx on public.network_regions(manager_user_id) where manager_user_id is not null;
create index network_clusters_org_idx on public.network_clusters(organization_id,brand_id,active);
create index network_cluster_stores_store_idx on public.network_cluster_stores(store_id);
create index establishments_network_scope_idx on public.establishments(organization_id,network_brand_id,network_region_id,ownership_type);
create index network_member_scopes_user_idx on public.network_member_scopes(organization_id,user_id,active);
create index network_policies_resolve_idx on public.network_governance_policies(organization_id,domain,config_key,scope_type,scope_id,effective_at desc) where superseded_at is null;
create index network_overrides_store_status_idx on public.network_config_overrides(store_id,status,created_at desc);
create index network_rollouts_org_status_idx on public.network_rollouts(organization_id,status,created_at desc);
create index network_rollout_targets_queue_idx on public.network_rollout_targets(rollout_id,status,created_at) where status in('pending','failed');
create index network_catalog_org_brand_idx on public.network_catalog_products(organization_id,brand_id,active);
create index network_catalog_store_sync_idx on public.network_catalog_store_state(store_id,sync_status);
create index network_price_scope_idx on public.network_price_policies(organization_id,scope_type,scope_id,effective_at desc);
create index network_price_history_store_idx on public.network_price_history(store_id,changed_at desc);
create index network_approved_supplier_scope_idx on public.network_approved_suppliers(organization_id,scope_type,scope_id,status);
create index supplier_requests_store_status_idx on public.supplier_approval_requests(store_id,status,created_at desc);
create index network_standards_scope_idx on public.network_operational_standards(organization_id,scope_type,scope_id,active);
create index network_standard_execution_store_idx on public.network_standard_executions(store_id,status,next_due_at);
create index network_audits_store_date_idx on public.network_internal_audits(store_id,audit_date desc);
create index network_corrective_store_status_idx on public.network_corrective_actions(store_id,status,due_at);
create index network_drift_store_status_idx on public.network_configuration_drift(store_id,status,detected_at desc);
create index governance_exceptions_store_status_idx on public.governance_exception_requests(store_id,status,created_at desc);
create index network_announcements_scope_idx on public.network_announcements(organization_id,scope_type,scope_id,published_at desc);
create index store_opening_org_status_idx on public.store_opening_projects(organization_id,status,updated_at desc);
create index fact_store_compliance_org_time_idx on public.fact_store_compliance(organization_id,measured_at desc);
create index fact_store_benchmark_org_metric_idx on public.fact_store_benchmarks(organization_id,metric_key,measured_at desc);
create index network_audit_org_time_idx on public.network_audit_events(organization_id,created_at desc);
create index network_audit_store_time_idx on public.network_audit_events(store_id,created_at desc) where store_id is not null;

do $$ declare t text; begin foreach t in array array['network_brands','network_regions','network_clusters','network_cluster_stores','network_role_templates','network_member_scopes','network_governance_policies','network_config_overrides','network_rollouts','network_rollout_stages','network_rollout_targets','network_catalog_products','network_catalog_store_state','network_menu_templates','pricing_zones','pricing_zone_stores','network_price_policies','network_price_history','network_approved_suppliers','network_supplier_agreements','supplier_approval_requests','network_operational_standards','network_standard_executions','network_internal_audits','network_corrective_actions','network_configuration_drift','governance_exception_requests','network_announcements','network_announcement_acknowledgements','store_opening_templates','store_opening_projects','fact_network_rollouts','fact_store_compliance','fact_governance_exceptions','fact_store_benchmarks','dim_brand','dim_region','dim_cluster','dim_store_ownership_type','network_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;

insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,certified,sensitive,allowed_dimensions) values
('network_revenue','Network Revenue','Receita aprovada no escopo autorizado.','sum(total_cents where is_approved)','analytics_fact_orders','organization/day','Rede','daily','BRL','fact',true,true,array['organization_id','brand_id','region_id','cluster_id','store_id','ownership_type']),
('store_growth','Store Growth','Variação da receita por unidade.','current_period / prior_period - 1','analytics_fact_orders','store/period','Rede','daily','percent','calculation',true,true,array['organization_id','brand_id','region_id','store_id']),
('network_margin','Network Margin','Margem gerencial estimada consolidada.','(revenue-estimated_cost)/revenue','analytics_fact_order_items','organization/period','Rede','daily','percent','estimate',true,true,array['organization_id','brand_id','region_id','store_id']),
('network_compliance_rate','Compliance Rate','Execuções internas conformes.','compliant / applicable','fact_store_compliance','organization/period','Governança','daily','percent','calculation',true,false,array['organization_id','brand_id','region_id','store_id']),
('network_rollout_success_rate','Rollout Success Rate','Unidades aplicadas com sucesso.','success / processed','fact_network_rollouts','rollout','Governança','near_realtime','percent','calculation',true,false,array['organization_id','rollout_type']),
('configuration_drift_rate','Configuration Drift Rate','Unidades fora do padrão vigente.','open drift / scoped stores','network_configuration_drift','organization/day','Governança','daily','percent','calculation',true,false,array['organization_id','brand_id','region_id','store_id']),
('store_benchmark_percentile','Store Benchmark Percentile','Percentil da unidade no grupo comparável.','rank / peer group size','fact_store_benchmarks','store/metric/day','Rede','daily','percentile','calculation',true,true,array['organization_id','brand_id','region_id','store_id','metric_key','peer_group']) on conflict(metric_key) do update set name=excluded.name,description=excluded.description,formula=excluded.formula,source_of_truth=excluded.source_of_truth,updated_at=now();
